$ErrorActionPreference = "Stop"
$path = "D:\optiflow\src\pages\consulta\RelatoriosOperacionais.tsx"
if (Test-Path $path) { throw "Arquivo ja existe - abortando para nao sobrescrever. Apague manualmente se quiser recriar." }

$b64 = ''
$bytes = [System.Convert]::FromBase64String($b64)
$text = [System.Text.Encoding]::UTF8.GetString($bytes)
$text = $text -replace "`n", "`r`n"
$utf8Bom = New-Object System.Text.UTF8Encoding($true)
[System.IO.File]::WriteAllText($path, $text, $utf8Bom)
Write-Host "RelatoriosOperacionais.tsx criado em $path"
Write-Host "Rode: npm run build"